text = """<!DOCTYPE html>\n<html lang=\"ko\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no, viewport-fit=cover\">\n    <title>네트워크 & IT 핵심 요약 쇼츠</title>\n    <style>\n        * { box-sizing: border-box; margin: 0; padding: 0; }\n        html, body {\n            width: 100%;\n            height: 100dvh;\n            background-color: #0b0f19;\n            color: #ffffff;\n            font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial, sans-serif;\n            overflow: hidden;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n        }\n        #shortsContainer {\n            position: relative;\n            width: 100%;\n            max-width: 450px;\n            height: 100dvh;\n            background: linear-gradient(135deg, #0f172a 0%, #090d16 100%);\n            overflow: hidden;\n            display: flex;\n            flex-direction: column;\n            justify-content: space-between;\n            padding: env(safe-area-inset-top, 20px) 20px env(safe-area-inset-bottom, 20px) 20px;\n        }\n        /* Start Overlay */\n        #startOverlay {\n            position: absolute;\n            top: 0; left: 0; width: 100%; height: 100%;\n            background: rgba(11, 15, 25, 0.95);\n            z-index: 9999;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            align-items: center;\n            cursor: pointer;\n            transition: opacity 0.5s ease;\n        }\n        .start-btn {\n            background: linear-gradient(135deg, #3b82f6 0%, #1d4ed8 100%);\n            color: white;\n            font-size: 1.2rem;\n            font-weight: bold;\n            padding: 16px 32px;\n            border-radius: 30px;\n            box-shadow: 0 0 20px rgba(59, 130, 246, 0.6);\n            animation: pulseBtn 1.5s infinite;\n            border: none;\n            outline: none;\n        }\n        @keyframes pulseBtn {\n            0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.7); }\n            70% { transform: scale(1.05); box-shadow: 0 0 0 15px rgba(59, 130, 246, 0); }\n            100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(59, 130, 246, 0); }\n        }\n        /* Header & Progress */\n        .header {\n            display: flex;\n            flex-direction: column;\n            gap: 8px;\n            z-index: 10;\n            padding-top: 10px;\n        }\n        .progress-bar-container {\n            width: 100%;\n            height: 4px;\n            background: rgba(255, 255, 255, 0.2);\n            border-radius: 2px;\n            overflow: hidden;\n            display: flex;\n            gap: 2px;\n        }\n        .progress-segment {\n            flex: 1;\n            height: 100%;\n            background: rgba(255, 255, 255, 0.4);\n            transition: background 0.3s;\n        }\n        .progress-segment.active {\n            background: #3b82f6;\n        }\n        .badge {\n            align-self: flex-start;\n            background: rgba(59, 130, 246, 0.2);\n            color: #60a5fa;\n            font-size: 0.75rem;\n            font-weight: 700;\n            padding: 4px 10px;\n            border-radius: 20px;\n            border: 1px solid rgba(59, 130, 246, 0.4);\n            text-transform: uppercase;\n            letter-spacing: 1px;\n        }\n        /* Main Scene View */\n        .scene-body {\n            flex: 1;\n            display: flex;\n            flex-direction: column;\n            justify-content: center;\n            align-items: center;\n            position: relative;\n            z-index: 10;\n            text-align: center;\n            padding: 10px 0;\n        }\n        h1.title {\n            font-size: 1.8rem;\n            font-weight: 800;\n            margin-bottom: 12px;\n            background: linear-gradient(to right, #60a5fa, #c084fc);\n            -webkit-background-clip: text;\n            -webkit-text-fill-color: transparent;\n            line-height: 1.3;\n        }\n        p.desc {\n            font-size: 1rem;\n            color: #94a3b8;\n            line-height: 1.5;\n            max-width: 320px;\n        }\n        /* Visual Container */\n        .visual-box {\n            width: 100%;\n            height: 180px;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            margin-bottom: 20px;\n            position: relative;\n        }\n        /* Footer / Branding */\n        .footer {\n            display: flex;\n            justify-content: space-between;\n            align-items: center;\n            font-size: 0.75rem;\n            color: #64748b;\n            z-index: 10;\n            padding-bottom: 10px;\n            border-top: 1px solid rgba(255, 255, 255, 0.05);\n            padding-top: 10px;\n        }\n        /* Animations & SVG Styling */\n        .node-circle {\n            fill: #1e293b;\n            stroke: #3b82f6;\n            stroke-width: 3px;\n            transition: all 0.3s;\n        }\n        .pulse-ring {\n            animation: svgPulse 2s infinite;\n            transform-origin: center;\n            transform-box: fill-box;\n        }\n        @keyframes svgPulse {\n            0% { transform: scale(0.95); opacity: 0.8; }\n            50% { transform: scale(1.1); opacity: 0.3; }\n            100% { transform: scale(0.95); opacity: 0.8; }\n        }\n        .data-packet {\n            fill: #60a5fa;\n            filter: drop-shadow(0 0 6px #3b82f6);\n        }\n    </style>\n</head>\n<body>\n\n<div id=\"shortsContainer\">\n    <!-- 오토플레이 정책 우회 오버레이 -->\n    <div id=\"startOverlay\" onclick=\"startExperience()\">\n        <button class=\"start-btn\">▶ 쇼츠 영상 시작하기</button>\n    </div>\n\n    <!-- 헤더 / 상단 진행바 -->\n    <div class=\"header\">\n        <div class=\"progress-bar-container\" id=\"progressBarContainer\"></div>\n        <div class=\"badge\" id=\"sceneBadge\">NETWORKING</div>\n    </div>\n\n    <!-- 컨텐츠 영역 -->\n    <div class=\"scene-body\">\n        <div class=\"visual-box\" id=\"visualBox\"></div>\n        <h1 class=\"title\" id=\"sceneTitle\">제목 로딩중...</h1>\n        <p class=\"desc\" id=\"sceneDesc\">설명 로딩중...</p>\n    </div>\n\n    <!-- 푸터 -->\n    <div class=\"footer\">\n        <span>⚡ Tech Shorts Master</span>\n        <span id=\"sceneCounter\">1 / 10</span>\n    </div>\n</div>\n\n<script>\n    const scenes = [\n        {\n            badge: \"LAYER 2 / ETHERNET\",\n            title: \"이더넷 & MAC 주소\",\n            desc: \"동일 네트워크 대역 기기 간 통신을 위한 2계층 기술, 기기 고유의 물리적 주소인 MAC Address를 사용합니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <rect x=\"20\" y=\"60\" width=\"60\" height=\"40\" rx=\"8\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n                    <text x=\"50\" y=\"85\" fill=\"#94a3b8\" font-size=\"10\" text-anchor=\"middle\">PC A</text>\n                    <rect x=\"200\" y=\"60\" width=\"60\" height=\"40\" rx=\"8\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"230\" y=\"85\" fill=\"#94a3b8\" font-size=\"10\" text-anchor=\"middle\">PC B</text>\n                    <line x1=\"80\" y1=\"80\" x2=\"200\" y2=\"80\" stroke=\"#64748b\" stroke-width=\"2\" stroke-dasharray=\"4\"/>\n                    <circle class=\"data-packet\" cx=\"110\" cy=\"80\" r=\"6\">\n                        <animate attributeName=\"cx\" values=\"90;190;90\" dur=\"2s\" repeatCount=\"indefinite\"/>\n                    </circle>\n                    <text x=\"140\" y=\"55\" fill=\"#3b82f6\" font-size=\"10\" text-anchor=\"middle\">MAC Address</text>\n                </svg>\n            `\n        },\n        {\n            badge: \"TOPOLOGY\",\n            title: \"네트워크 토폴로지 구조\",\n            desc: \"Bus, Star, Ring, Tree, Mesh 등 노드 연결 형태에 따라 비용, 신뢰성, 확장성이 달라집니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <!-- Star Topology -->\n                    <circle cx=\"140\" cy=\"80\" r=\"16\" fill=\"#3b82f6\" class=\"pulse-ring\"/>\n                    <circle cx=\"140\" cy=\"80\" r=\"12\" fill=\"#1e293b\" stroke=\"#60a5fa\" stroke-width=\"2\"/>\n                    <circle cx=\"80\" cy=\"40\" r=\"10\" fill=\"#1e293b\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n                    <circle cx=\"200\" cy=\"40\" r=\"10\" fill=\"#1e293b\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n                    <circle cx=\"80\" cy=\"120\" r=\"10\" fill=\"#1e293b\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n                    <circle cx=\"200\" cy=\"120\" r=\"10\" fill=\"#1e293b\" stroke=\"#94a3b8\" stroke-width=\"2\"/>\n                    <line x1=\"130\" y1=\"70\" x2=\"90\" y2=\"45\" stroke=\"#475569\" stroke-width=\"2\"/>\n                    <line x1=\"150\" y1=\"70\" x2=\"190\" y2=\"45\" stroke=\"#475569\" stroke-width=\"2\"/>\n                    <line x1=\"130\" y1=\"90\" x2=\"90\" y2=\"115\" stroke=\"#475569\" stroke-width=\"2\"/>\n                    <line x1=\"150\" y1=\"90\" x2=\"190\" y2=\"115\" stroke=\"#475569\" stroke-width=\"2\"/>\n                </svg>\n            `\n        },\n        {\n            badge: \"SWITCHING NETWORK\",\n            title: \"회선 vs 메시지 vs 패킷 교환\",\n            desc: \"패킷 교환은 데이터를 패킷 단위로 잘게 쪼개어 전송하며 비연결성으로 블로킹이 없습니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <rect x=\"30\" y=\"65\" width=\"40\" height=\"30\" rx=\"4\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n                    <rect x=\"210\" y=\"65\" width=\"40\" height=\"30\" rx=\"4\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <path d=\"M 75 80 Q 140 30 205 80\" fill=\"none\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"4\"/>\n                    <path d=\"M 75 80 Q 140 130 205 80\" fill=\"none\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"4\"/>\n                    <circle cx=\"140\" cy=\"55\" r=\"5\" fill=\"#60a5fa\">\n                        <animateMotion path=\"M -65 25 Q 0 -25 65 25\" dur=\"1.5s\" repeatCount=\"indefinite\"/>\n                    </circle>\n                    <circle cx=\"140\" cy=\"105\" r=\"5\" fill=\"#f43f5e\">\n                        <animateMotion path=\"M -65 25 Q 0 75 65 25\" dur=\"1.5s\" repeatCount=\"indefinite\"/>\n                    </circle>\n                </svg>\n            `\n        },\n        {\n            badge: \"LAN PROTOCOL\",\n            title: \"CSMA/CD & CSMA/CA\",\n            desc: \"유선랜(802.3)은 충돌 감지(CD) 후 재전송, 무선랜(802.11)은 충돌 회피(CA) 메커니즘을 사용합니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <line x1=\"40\" y1=\"80\" x2=\"240\" y2=\"80\" stroke=\"#3b82f6\" stroke-width=\"4\"/>\n                    <circle cx=\"100\" cy=\"80\" r=\"12\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <circle cx=\"180\" cy=\"80\" r=\"12\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <circle cx=\"140\" cy=\"50\" r=\"8\" fill=\"#ef4444\">\n                        <animate attributeName=\"opacity\" values=\"0;1;0\" dur=\"1s\" repeatCount=\"indefinite\"/>\n                    </circle>\n                    <text x=\"140\" y=\"110\" fill=\"#f59e0b\" font-size=\"12\" text-anchor=\"middle\">Collision Avoidance / Detect</text>\n                </svg>\n            `\n        },\n        {\n            badge: \"ERROR CONTROL\",\n            title: \"에러 검출 및 ARQ 방식\",\n            desc: \"패리티 검사, CRC, 해밍코드로 에러를 검출하고, Stop-and-Wait 등으로 재전송(BEC)을 수행합니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <rect x=\"50\" y=\"60\" width=\"60\" height=\"40\" rx=\"6\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"80\" y=\"85\" fill=\"#10b981\" font-size=\"12\" text-anchor=\"middle\">CRC</text>\n                    <rect x=\"170\" y=\"60\" width=\"60\" height=\"40\" rx=\"6\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n                    <text x=\"200\" y=\"85\" fill=\"#3b82f6\" font-size=\"12\" text-anchor=\"middle\">ARQ</text>\n                    <path d=\"M 110 70 Q 140 40 170 70\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"2\"/>\n                    <path d=\"M 170 90 Q 140 120 110 90\" fill=\"none\" stroke=\"#f43f5e\" stroke-width=\"2\" stroke-dasharray=\"3\"/>\n                </svg>\n            `\n        },\n        {\n            badge: \"STORAGE / RAID\",\n            title: \"RAID 기술 개요\",\n            desc: \"RAID 0(스트라이핑)부터 미러링(1), 분산 패리티(5, 6)를 통해 성능 향상과 데이터 안정성을 확보합니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <rect x=\"70\" y=\"30\" width=\"140\" height=\"25\" rx=\"4\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n                    <rect x=\"70\" y=\"65\" width=\"140\" height=\"25\" rx=\"4\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <rect x=\"70\" y=\"100\" width=\"140\" height=\"25\" rx=\"4\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <text x=\"140\" y=\"47\" fill=\"#60a5fa\" font-size=\"11\" text-anchor=\"middle\">Disk 0 (Striping)</text>\n                    <text x=\"140\" y=\"82\" fill=\"#34d399\" font-size=\"11\" text-anchor=\"middle\">Disk 1 (Mirroring)</text>\n                    <text x=\"140\" y=\"117\" fill=\"#fbbf24\" font-size=\"11\" text-anchor=\"middle\">Disk 2 (Parity)</text>\n                </svg>\n            `\n        },\n        {\n            badge: \"ROUTING PROTOCOL\",\n            title: \"RIP, OSPF, BGP 라우팅\",\n            desc: \"거리벡터 방식의 RIP, 링크상태 기반의 OSPF, AS 간 연결을 담당하는 BGP 프로토콜이 있습니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <circle cx=\"60\" cy=\"80\" r=\"16\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n                    <circle cx=\"140\" cy=\"40\" r=\"16\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <circle cx=\"140\" cy=\"120\" r=\"16\" fill=\"#1e293b\" stroke=\"#f59e0b\" stroke-width=\"2\"/>\n                    <circle cx=\"220\" cy=\"80\" r=\"16\" fill=\"#1e293b\" stroke=\"#c084fc\" stroke-width=\"2\"/>\n                    <line x1=\"74\" y1=\"70\" x2=\"126\" y2=\"50\" stroke=\"#64748b\" stroke-width=\"2\"/>\n                    <line x1=\"74\" y1=\"90\" x2=\"126\" y2=\"110\" stroke=\"#64748b\" stroke-width=\"2\"/>\n                    <line x1=\"154\" y1=\"50\" x2=\"206\" y2=\"70\" stroke=\"#64748b\" stroke-width=\"2\"/>\n                    <line x1=\"154\" y1=\"110\" x2=\"206\" y2=\"90\" stroke=\"#64748b\" stroke-width=\"2\"/>\n                </svg>\n            `\n        },\n        {\n            badge: \"DNS SYSTEM\",\n            title: \"DNS 레코드와 라운드로빈\",\n            desc: \"A, CNAME, MX 레코드 등 도메인 정보를 관리하며, 라운드로빈 방식으로 서버 부하를 분산합니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <rect x=\"90\" y=\"20\" width=\"100\" height=\"35\" rx=\"6\" fill=\"#1e293b\" stroke=\"#3b82f6\" stroke-width=\"2\"/>\n                    <text x=\"140\" y=\"42\" fill=\"#60a5fa\" font-size=\"12\" text-anchor=\"middle\">DNS Server</text>\n                    <path d=\"M 140 55 L 70 110\" stroke=\"#64748b\" stroke-width=\"2\"/>\n                    <path d=\"M 140 55 L 140 110\" stroke=\"#64748b\" stroke-width=\"2\"/>\n                    <path d=\"M 140 55 L 210 110\" stroke=\"#64748b\" stroke-width=\"2\"/>\n                    <circle cx=\"70\" cy=\"125\" r=\"12\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <circle cx=\"140\" cy=\"125\" r=\"12\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <circle cx=\"210\" cy=\"125\" r=\"12\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                </svg>\n            `\n        },\n        {\n            badge: \"SECURITY & HTTP\",\n            title: \"IDS/IPS 및 HTTP 상태코드\",\n            desc: \"IDS는 사후 탐지, IPS는 실시간 차단! HTTP 200(성공), 400(클라이언트 오류), 500(서버 오류)을 의미합니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <rect x=\"40\" y=\"50\" width=\"80\" height=\"60\" rx=\"8\" fill=\"#1e293b\" stroke=\"#f43f5e\" stroke-width=\"2\"/>\n                    <text x=\"80\" y=\"85\" fill=\"#f43f5e\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">IPS 403</text>\n                    <rect x=\"160\" y=\"50\" width=\"80\" height=\"60\" rx=\"8\" fill=\"#1e293b\" stroke=\"#10b981\" stroke-width=\"2\"/>\n                    <text x=\"200\" y=\"85\" fill=\"#10b981\" font-size=\"14\" font-weight=\"bold\" text-anchor=\"middle\">HTTP 200</text>\n                </svg>\n            `\n        },\n        {\n            badge: \"PACKET SWITCHING\",\n            title: \"가상 회선 vs 데이터그램\",\n            desc: \"가상 회선은 사전 경로 설정(연결지향), 데이터그램은 패킷별 독립 전송(비연결성) 방식을 사용합니다.\",\n            visual: `\n                <svg width=\"280\" height=\"160\" viewBox=\"0 0 280 160\">\n                    <path d=\"M 40 80 Q 140 20 240 80\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"3\"/>\n                    <path d=\"M 40 80 Q 140 140 240 80\" fill=\"none\" stroke=\"#f59e0b\" stroke-width=\"3\" stroke-dasharray=\"4\"/>\n                    <circle cx=\"140\" cy=\"50\" r=\"6\" fill=\"#60a5fa\"/>\n                    <circle cx=\"140\" cy=\"110\" r=\"6\" fill=\"#fbbf24\"/>\n                    <text x=\"140\" y=\"85\" fill=\"#94a3b8\" font-size=\"11\" text-anchor=\"middle\">Virtual Circuit / Datagram</text>\n                </svg>\n            `\n        }\n    ];\n\n    let currentScene = 0;\n    let speechStarted = false;\n    let isStarted = false;\n    let synth = window.speechSynthesis;\n\n    // 진행바 동적 생성\n    const progressBarContainer = document.getElementById('progressBarContainer');\n    scenes.forEach((_, idx) => {\n        const seg = document.createElement('div');\n        seg.className = 'progress-segment';\n        seg.id = `seg-${idx}`;\n        progressBarContainer.appendChild(seg);\n    });\n\n    function startExperience() {\n        if (isStarted) return;\n        isStarted = true;\n\n        const overlay = document.getElementById('startOverlay');\n        overlay.style.opacity = '0';\n        setTimeout(() => overlay.remove(), 500);\n\n        // 음성 엔진 언락 (빈 utterance 발화)\n        if (synth) {\n            const unlockUtterance = new SpeechSynthesisUtterance(\"\");\n            synth.speak(unlockUtterance);\n        }\n\n        playScene(0);\n    }\n\n    function updateProgress(idx) {\n        scenes.forEach((_, i) => {\n            const seg = document.getElementById(`seg-${i}`);\n            if (i <= idx) {\n                seg.classList.add('active');\n            } else {\n                seg.classList.remove('active');\n            }\n        });\n    }\n\n    function playScene(index) {\n        if (index >= scenes.length) {\n            // 쇼츠 종료 시 반복 또는 완료 처리\n            currentScene = 0;\n            playScene(0);\n            return;\n        }\n\n        currentScene = index;\n        const scene = scenes[index];\n\n        // UI 렌더링\n        document.getElementById('sceneBadge').innerText = scene.badge;\n        document.getElementById('sceneTitle').innerText = scene.title;\n        document.getElementById('sceneDesc').innerText = scene.desc;\n        document.getElementById('visualBox').innerHTML = scene.visual;\n        document.getElementById('sceneCounter').innerText = `${index + 1} / ${scenes.length}`;\n        updateProgress(index);\n\n        // 음성 합성\n        if (synth) {\n            synth.cancel();\n            speechStarted = false;\n\n            const utterance = new SpeechSynthesisUtterance(scene.title + \". \" + scene.desc);\n            utterance.rate = 1.15;\n            utterance.pitch = 1.0;\n            utterance.lang = 'ko-KR';\n\n            utterance.onstart = () => {\n                speechStarted = true;\n            };\n\n            utterance.onend = () => {\n                if (speechStarted) {\n                    playScene(currentScene + 1);\n                }\n            };\n\n            utterance.onerror = () => {\n                // 에러 발생 시에도 끊김 없이 다음 장면으로 넘어가도록 처리\n                setTimeout(() => playScene(currentScene + 1), 1000);\n            };\n\n            // 약간의 딜레이 후 발화 실행\n            setTimeout(() => {\n                synth.speak(utterance);\n            }, 100);\n        } else {\n            // 음성 지원이 안되는 브라우저 대비 폴백 타이머\n            setTimeout(() => playScene(currentScene + 1), 4000);\n        }\n    }\n</script>\n\n</body>\n</html>"""
f = open("test/test.html", "w")
f.write(text)
f.close()